@Service
@RequiredArgsConstructor
public class KbService {
    private final VectorStore vectorStore;
    private final ChatClient.Builder chatClientBuilder;

    // 入库：读取 -> 分块 -> 写入（内部自动 Embedding）
    public void ingest(Resource pdf, String dept) {
        List<Document> docs = new TikaDocumentReader(pdf).get();
        List<Document> chunks = TokenTextSplitter.builder().withChunkSize(500).build().apply(docs);
        chunks.forEach(d -> d.getMetadata().put("dept", dept));
        vectorStore.add(chunks);
    }

    // 问答：检索增强 + 按部门过滤
    public String ask(String question, String dept) {
        var advisor = QuestionAnswerAdvisor.builder(vectorStore)
                .searchRequest(SearchRequest.builder()
                        .topK(5)
                        .similarityThreshold(0.6)
                        .filterExpression("dept == '" + dept + "'")
                        .build())
                .build();
        return chatClientBuilder.build().prompt()
                .advisors(advisor)
                .user(question)
                .call()
                .content();
    }
}
// 生产中 dept 来自登录态，勿直接拼接用户输入；也可用 FilterExpressionBuilder 构造。

