@Service
@RequiredArgsConstructor
public class DifyClient {
    private final RestClient rest = RestClient.builder()
            .baseUrl("https://dify.internal/v1").build();
    @Value("${dify.api-key}") private String apiKey;          // 放配置中心，勿写死

    public String chat(String userId, String query, String conversationId) {
        Map<String, Object> body = Map.of(
                "inputs", Map.of(),
                "query", query,
                "response_mode", "blocking",                   // 流式用 streaming（SSE）
                "conversation_id", conversationId == null ? "" : conversationId,
                "user", userId);
        JsonNode resp = rest.post().uri("/chat-messages")
                .header("Authorization", "Bearer " + apiKey)
                .body(body).retrieve().body(JsonNode.class);
        return resp.path("answer").asText();
    }
}

